#include <stdio.h>

int inc(char *s, int len) {
    int i = len - 1;
    while (i >= 0 && s[i] == '9') {
        s[i] = '0';
        i--;
    }
    if (i < 0) {
        s[len] = '0';
        for (int j = len; j > 0; j--) {
            s[j] = s[j - 1];
        }
        s[0] = '1';
        return len + 1;
    } else {
        s[i]++;
        return len;
    }
}

int match(char *cur, int len, char *S, int pos, int N) {
    if (pos + len > N) return 0;
    for (int i = 0; i < len; i++) {
        if (cur[i] != S[pos + i]) return 0;
    }
    return 1;
}

