    int N;
    scanf("%d", &N);
    char S[1005];
    for (int i = 0; i < N; i++) {
        int d;
        scanf("%d", &d);
        S[i] = d + '0';
    }
    S[N] = '\0';

    char cur[1005];
    for (int l = 1; l <= N; l++) {
        if (S[0] == '0') continue;
        for (int i = 0; i < l; i++) cur[i] = S[i];
        int len = l;
        int pos = l;
        int ok = 1;
        while (pos < N) {
            len = inc(cur, len);
            if (!match(cur, len, S, pos, N)) {
                ok = 0;
                break;
            }
            pos += len;
        }
        if (ok) {
            for (int i = 0; i < l; i++) putchar(S[i]);
            putchar('\n');
            return 0;
        }
    }
    return 0;
}
